INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Mustela Cicastela Crème Réparatrice 40ml','Mustela','Bébé & Maman','Mustela Cicastela Crème Réparatrice 40ml

