INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SKIN 1004 MADAGASCAR CENTELLA QUICK CALMING DUO','Skin 1004','Solaires','Skin1004 Madagascar Centella Quick Calming Duo
