INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HUBMLE BROSSE A DENTS BAMBOU ADULTE — Jaune','The Humble','Hygiène','HUBMLE BROSSE A DENTS BAMBOU ADULTE BLUE

