INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revolution Mascara Big Lash Waterproof Volume','Revolution','Maquillage','Le mascara imperméable Revolution BigLash XL est le mascara volumisant par excellence.

