INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION PALETTE EYESHADOW FOREVER FLAWLESS ALLURE','Revolution','Autres soins','Affichez un look impeccable grâce à la palette Forever Flawless Allure. Avec ses 18 fards à paupières mats ou irisés, et ses ombres pailletées, pressées et marbrées, vous avez l''embarras du choix !

