INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CETAPHIL COFFRET SUN LOTION SPF50+ 100ML + PROTECTIVE BAUME A LEVRES 8ML OFFERT','Cetaphil','Solaires','C’est une crème solaire adaptée à la protection des peaux sensibles et sèches, facile à appliquer et à absorption rapide, non collante et non grasse pour une agréable sensation sur la peau. Les filtres UVA stables offrent une protection UVA et UVB très efficace et immédiate, protègent efficacement les cellules et préviennent le vieillissement cutané causé par le soleil. La formule des liposomes permet une distribution homogène des filtres UV, avec une distribution facile et une absorption instantanée, assurant une haute protection contre les rayons du soleil. Tout cela en plus de la lotion solaire Cetaphil contenant de l’aloe vera et de la vitamine E, qui hydratent et protègent la peau du dessèchement et la protègent des signes du vieillissement.',21800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cetaphil-sun-lotion-spf50-100ml-achete-cetaphil-baume-a-levres-protecteur-spf50-8-ml-offert.webp?v=1766767283',10,1,'8454143443119','46435342778543','https://beautymarket.ma/products/cetaphil-coffret-sun-lotion-spf50-100ml-protective-baume-a-levres-8ml-offert',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cetaphil-sun-lotion-spf50-100ml-achete-cetaphil-baume-a-levres-protecteur-spf50-8-ml-offert.webp?v=1766767283"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NIACINAZ CREME PURE NIACINAMIDE 10% 50 ML','Niacinaz','Solaires','La Crème Pure Niacinamide 10% de NiacinAZ est un soin puissant qui révolutionne votre routine de soins de la peau. Grâce à sa formule enrichie en niacinamide (vitamine B3), elle cible efficacement les problèmes de pigmentation et aide à lutter contre le vieillissement cutané tout en maintenant une hydratation optimale. La niacinamide agit en profondeur pour atténuer les taches pigmentaires, réduire les rougeurs et calmer les irritations, vous offrant une peau plus lumineuse et un teint uniformisé.

Bienfaits principaux :

Lutte contre les signes du vieillissement : Réduit l''apparence des ridules et des rides tout en raffermissant la peau, pour un visage plus jeune et tonifié.
Unifie et illumine le teint : Grâce à sa concentration en niacinamide (10%), cette crème cible les taches pigmentaires et améliore la texture de la peau.
Propriétés anti-inflammatoires : Calme les inflammations cutanées, tout en prévenant les rougeurs et autres imperfections.
Hydratation longue durée : Maintient un niveau d''hydratation optimal tout au long de la journée, sans effet gras.

Actifs clés :

Niacinamide : Diminue la taille des pores et améliore la texture de la peau, tout en favorisant la production de kératine.
Vitamine E : Anti-oxydant puissant, elle protège la peau contre les radicaux libres, réduisant le vieillissement prématuré et renforçant la barrière cutanée.

Conseils d’utilisation :

Appliquez la crème matin et soir sur une peau propre, en étalant délicatement sur le visage, le cou et le décolleté. Elle peut être utilisée comme traitement d''entretien quotidien pour prévenir l’apparition des taches futures et améliorer visiblement la texture de la peau. Sa texture non grasse et non comédogène convient à tous les types de peau.',21400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/niacinaz-creme-pure-niacinamide-10-50-ml.jpg?v=1766769142',10,1,'8454148882607','46435349037231','https://beautymarket.ma/products/niacinaz-creme-pure-niacinamide-10-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/niacinaz-creme-pure-niacinamide-10-50-ml.jpg?v=1766769142"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Racine Vita Pack contour des yeux','Racine Vita','Visage','SÉRUM INTENSIF CONTOUR YEUX A BASE DE L''ACIDE HYALURONIQUE- RÉTINOL- PRO-VITAMINE B5-VITAMINE C et E triple action soin contour yeux anti rides et ridules',4900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_1_5d07ddd3-dce1-4e74-8cc7-3cf7d7b8cf8f.jpg?v=1766773854',10,1,'8454192300207','46435426205871','https://beautymarket.ma/products/racine-vita-pack-contour-des-yeux',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_1_5d07ddd3-dce1-4e74-8cc7-3cf7d7b8cf8f.jpg?v=1766773854"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Racine Vita PACK NIACINAMIDE SERUM 10ML= VITAMINE E SERUM 10ML offert','Racine Vita','Cheveux','Le sérum Racine Vita à la niacinamide (vitamine B3) en format de 10 ml est un traitement cosmétique réputé pour ses propriétés bénéfiques pour la peau. La niacinamide est connue pour ses capacités apaisantes et hydratantes, aidant à réduire l''apparence des pores, à équilibrer la production de sébum et à améliorer la texture globale de la peau. Ce sérum est souvent recommandé pour les peaux sujettes aux imperfections, offrant une solution efficace.

La Vitamine E (ou Tocophérol) est une vitamine liposoluble (soluble dans les huiles mais pas dans l’eau).
Reconnue pour ses propriétés antioxydantes et son action protectrice des membranes cellulaires, elle est utilisée pour conserver les préparations à forte teneur en huiles car elle évite leur rancissement.
La vitamine E est également reconnue pour ses propriétés hydratantes et pour son action sur la microcirculation cutanée.
Elle assure donc un rôle à la fois de conservateur et d’agent d’entretien de la peau. 100% naturelle.
-antioxydant assure un rôle de conservateur au niveau des préparations , et protège les huiles et beurres du rancissement .
-Un excellent actif anti-âge , particulièrement recommandé pour les peaux sèches et natures
-Bloque l’action des radiaux libres sur la peau .
-Améliore la microcirculation cutanée
-Aide à maintenir l’élasticité et l’hydratation de la peau en renforçant le film hydrolipidique cutané.
-Activité anti-inflammatoire sur la peau, (utile en cas de coups de soleil, …)',6500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Designsanstitre_43.png?v=1766774570',10,1,'8454193348783','46435427549359','https://beautymarket.ma/products/racine-vita-pack-2in1-racine-vita-niacinamide-serum-10ml-vitamine-e-serum-10ml-offert',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Designsanstitre_43.png?v=1766774570"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
