INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GUM MANCHE AVEC FIL FLOSBRUSH AUTOMATIC REF 847','Gum','Hygiène','Le porte-fil GUM FLOSBRUSH Automatic est un accessoire d’hygiène interdentaire unique, doté d’un mécanisme spécialement conçu pour déployer une nouvelle section de fil dentaire grâce à un levier. C’est pour vous l’assurance d’utiliser du fil propre.

