INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VERTU PLUS NOPAL BIO 90 GÉLULES','Vertu Plus','Bien-être','NOPAL BIO de Vertuplus est un complément alimentaire naturel à base de Nopal (Opuntia ficus-indica), une plante reconnue pour ses propriétés minceur et son action coupe-faim. Riche en fibres naturelles, le nopal contribue à augmenter la sensation de satiété et aide à réduire l’appétit, dans le cadre d’un mode de vie sain et équilibré.

