INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CONFORT THERMOMÈTRE FLEXIBLE MÉDICAL DIGITAL DMT-3062 CANARD','Confort','Bébé & Maman','Thermomètre numérique avec embout flexible – Confort est idéal pour des mesures précises. Il convient aux mesures rectales, orales et axillaires, aussi bien aux enfants qu’aux adultes. Un signal sonore vous avertit à la fin de la mesure ou en cas de température élevée, vous permettant de réagir rapidement.

La température est mesurée en 30 secondes, un temps particulièrement apprécié des enfants agités. Sa conception étanche garantit un nettoyage facile et sûr, et son embout flexible garantit une utilisation confortable et sûre, sans mercure.

Appuyez sur le bouton d’alimentation pour allumer l’appareil

Pointez le capteur de température en bonne position, attendez le bip sonore

Lire la température

Appuyez sur le bouton d’alimentation pour éteindre l’appareil

Haute précision et annonce rapide

La mémoire affiche la dernière lecture

Bips à la température maximale

Fonction d’arrêt automatique

Sonde incassable et sans danger pour les enfants

Plus de 200 heures de fonctionnement continu

Plage de mesure : 32.0°C- 43.9°C(89.6 °F-111.9 °F)

Précision :  ±0.1°C,35.5°C – 42.0°C (±0.2°F,95.9 °F-107.6°F)

Piles :1.5V(LR41) – Incluses',3500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/CONFORTTT.png?v=1767726803',10,1,'8460604899503','46462588846255','https://beautymarket.ma/products/confort-thermometre-flexible-medical-digital-dmt-3062-canard',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/CONFORTTT.png?v=1767726803"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
