INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('COVERMARK RAYBLOCK FACE PLUS VISIBLE DRY SENSITIVE SPF50+ 50ML','Covermark','Solaires','• Protège la peau avec un SPF50+ très haute protection.

 • Camoufle les petites imperfections (taches, rougeurs, cicatrices légères).

