INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Manix King Size Ultra Preservatifs 2','Manix','Visage','KING SIZE ULTRA est le préservatif leader dans la catégorie des grandes tailles. Ce préservatif est plus large et plus fin qu''un préservatif Manix standard pour offrir plus de confort et maintenir la sensibilité. Ces préservatifs sont fabriqués en latex de caoutchouc naturel, qui peut provoquer des réactions allergiques, y compris des symptômes anaphylactiques. Les préservatifs Manix, lorsqu''ils sont utilisés correctement, peuvent réduire le risque de grossesse, de VIH/SIDA et de nombreuses maladies sexuellement transmissibles. Aucun contraceptif ne peut garantir une protection à 100 %.',1900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MANIX_XL.png?v=1768228258',10,1,'8468003815599','46479777202351','https://beautymarket.ma/products/manix-king-size-ultra-2',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MANIX_XL.png?v=1768228258"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
