INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('AVENT BIBERON NATURAL EN VERRE 3.0 TEAT 3-6 M 240ML SCY933/01','Philips Avent','Bébé & Maman','Tétine à Réponse Naturelle : la tétine de ce biberon Philips Avent permet au bébé de téter et de se nourrir confortablement à son propre rythme.
• Fonctionne comme le sein : la tétine libère le lait lorsque le bébé tète activement, ce qui est différent des tétines traditionnelles à débit libre. Comme pour l’allaitement, il faut du temps pour que le bébé s’y habitue.
• Valve anti-coliques : les biberons Philips Avent sont conçus pour empêcher l’air d’entrer dans le ventre du bébé pendant la tétée.
• Le bon débit pour la tétine : trouvez le débit idéal pour votre bébé et personnalisez votre biberon Philips Avent.
• Tétine anti-goutte : l’ouverture de la tétine du biberon libère le lait uniquement lorsque le bébé tète.',21500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71X-XHRayTL._AC_UF1000_1000_QL80.jpg?v=1790265199',10,1,'8470045687983','46488897061039','https://beautymarket.ma/products/avent-biberon-natural-en-verre-3-0-teat-1m-240ml-scy933-01',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71X-XHRayTL._AC_UF1000_1000_QL80.jpg?v=1790265199"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
