INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DIETAROMA OLÉOPOLIS SIROP GORGE 125 ml','Dietaroma','Corps','Le sirop Oleopolis® de Dietaroma est un complément alimentaire formulé à partir d’extraits de plantes reconnues pour leurs bienfaits sur les voies respiratoires. Il aide à apaiser la gorge, calmer la toux et favoriser une respiration plus confortable, notamment en cas d’irritations ou de sensibilités liées au froid ou aux changements de saison.
