INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Yogi Tea - CHILI DOUX 17 Sachets','Yogi Tea','Corps','Réglisse*, coques de cacao*, menthe verte*, fenouil*, anis*, gingembre*, menthe poivrée*, ortie*, cannelle*, piment*, cardamome*, clous de girofle*, poivre noir*

