INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URBAN CARE PINK ALLURE PARFUM CHEVEUX 50 ML','Urban Care','Cheveux','Le Parfum pour Cheveux URBAN Care Pink Allure possède une formule spéciale, inspirée par les parfumeurs, qui marie les notes florales et élégantes du jasmin, la douceur chaleureuse de l’ambre et le parfum boisé et sophistiqué du cèdre.

