INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URBAN CARE BRAZILIAN KERATIN LISSAGE A LA KERATINE 75 ML','Urban Care','Cheveux','La Cure Lissante à la Kératine URBAN Care Brazilian Keratin est une solution capillaire intensive à la formule spécialement développée pour offrir un soin nourrissant et hydratant, tout en procurant immédiatement des cheveux plus lisses, brillants et faciles à coiffer.

