INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URBAN CARE PURPLE SHAMPOOING 250ML','Urban Care','Cheveux','Shampooing Soin Violet Sans Sulfates Anti-reflets Cuivrés
