INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NATRACARE TAMPONS SUPER SANS APPLICATEUR 10 U','Natracare','Hygiène','Les tampons Natracare sans applicateur sont fabriqués en coton 100 % biologique. Au fur et à mesure que le coton absorbe le flux menstruel tout en douceur, le tampon s’élargit.

