INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Nutritive Bain Satin 250ml – Shampooing Nourrissant Cheveux Normaux à Secs','Kérastase','Cheveux','Le Bain Satin de la gamme Nutritive de Kérastase est un shampoing doux et hydratant pour les cheveux secs. Les cheveux secs sont hydratés et renforcés.

