INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Chroma Absolu Masque Chroma Filler 200ml – Masque Réparateur Cheveux Colorés','Kérastase','Cheveux','Masque anti-porosité, développé pour les cheveux colorés sensibilisés ou abîmés. Ce soin pénètre au cœur de la fibre capillaire pour augmenter la force en réduisant la porosité des cheveux moyens à épais. Les cheveux sont renforcés et nourris. La brillance et l''intensité de la couleur sont préservées de façon plus durable.

Le Masque Chroma Filler est un masque anti-porosité, développé pour les cheveux colorés sensibilisés ou abîmés. Sa crème riche rose pâle pénètre en profondeur dans la fibre capillaire pour combler la porosité et renforcer les cheveux normaux à épais pour une couleur plus intense et plus brillante. Ce soin est enrichi d''une combinaison puissante d''acides aminés et de Centella Asiatica offre aux cheveux un soin puissant. Les mèches sont 92% plus fortes(1), plus résistantes et 93% plus nourries(1) avec une porosité réduite pour une couleur plus durable.

Utilisation après utilisation, les cheveux deviennent 62% plus brillants(2) et plus éclatants et 92% de l''intensité de la couleur est préservée après 6 semaines(3).

9/10 femmes affirment que les cheveux sont nourris, hydratés et renforcés (4).

(1) TEST INSTRUMENTAL

(2) TEST INSTRUMENTAL : BAIN RICHE CHROMA RESPECT + SOIN ACIDE CHROMA GLOSS + MASQUE CHROMA FILLER

(3) TEST INSTRUMENTAL : BAIN RICHE CHROMA RESPECT + MASQUE CHROMA FILLER

(4) TEST CONSOMMATEUR : BAIN RICHE CHROMA RESPECT + MASQUE CHROMA FILLER + SÉRUM CHROMA THERMIQUE".',41500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/63.png?v=1770198790',10,1,'8480716521647','46540722110639','https://beautymarket.ma/products/kerastase-chroma-absolu-masque-chroma-filler-200ml-masque-reparateur-cheveux-colores',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/63.png?v=1770198790","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059132.pt01_1.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059132.pt05.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_CHROMAABSOLU_MASQUECHROMAFILLER_3474637059132_PRODUCTSINHAND_065ec2ba-cdca-489b-8775-1b72990f86ef.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_CHROMAABSOLU_MASQUECHROMAFILLER_3474637059132_ECOMM.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059132.pt02.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059248.pt02_c276d304-68f5-4956-8452-9811450a7014.jpg?v=1771511799","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059248.pt03_7cc434b1-bd05-4b39-b26c-83e5970e2475.jpg?v=1771512490","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059248.pt04_47cc5b24-8ad0-424d-b770-6763024003dc.jpg?v=1771512490"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Chroma Absolu Acide Chroma Gloss 210ml – Soin Brillance Cheveux Colorés','Kérastase','Cheveux','Soin de haute brillance resurfaçant pour sublimer tous les types de cheveux colorés. Sa texture transformatrice fluide-crème pénètre en profondeur pour hydrater et renforcer la fibre capillaire, tout en réduisant la porosité pour une couleur plus intense, plus brillante et avec moins de frisottis.

Le Soin Acide Chroma Gloss est un soin haute brillance resurfaçant pour tous les types de cheveux colorés. Ce soin a une texture fluide et transparente qui se transforme en une crème blanche lorsqu''elle est mélangée à l''eau pour pénétrer profondément dans le cheveu et augmenter jusqu''à 96% la force de la fibre(2) et apporter +94% d''hydratation(1). (1) TESTS INSTRUMENTAUX

(2) TEST INSTRUMENTAL : SOIN ACIDE CHROMA GLOSS + SÉRUM CHROMA THERMIQUE

(3) TEST INSTRUMENTAL : BAIN RICHE CHROMA RESPECT + SOIN ACIDE CHROMA GLOSS',41500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/65_45866729-cd97-412e-89d1-1bad9515562b.png?v=1770199852',10,1,'8480717635759','46540737839279','https://beautymarket.ma/products/kerastase-chroma-absolu-acide-chroma-gloss-210ml-soin-brillance-cheveux-colores',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/65_45866729-cd97-412e-89d1-1bad9515562b.png?v=1770199852","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KERASTASE_21_-_CHROMA_ABSOLU_-_All_Format_-_Soin_Acide_-_210ml_-_Side_-_EC1_501.png?v=1771512187","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059101.pt01.jpg?v=1771512187","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059101.pt05.jpg?v=1771512187","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_CHROMAABSOLU_SOINACIDECHROMAGLOSS_3474637059101_PRODUCTSINHAND.jpg?v=1771512187","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059248.pt03_7cc434b1-bd05-4b39-b26c-83e5970e2475.jpg?v=1771512490","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059248.pt04_47cc5b24-8ad0-424d-b770-6763024003dc.jpg?v=1771512490","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637059101.pt07.jpg?v=1771512170"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Blond Absolu Masque Cicaextreme 200ml – Masque Réparateur Intense Cheveux Blonds','Kérastase','Cheveux','Le masque Cicaextreme Blond Absolu de Kérastase est un masque à l''Acide Hyaluronique pour les cheveux décolorés. Si vous venez d''éclaircir ou de mécher vos cheveux, ils sont très sensibles et nécessitent un soin profond après la décoloration.

Ce gel-crème riche est enrichi en Acide Hyaluronique et en extrait de fleurs d''Edelweiss pour reconstruire les cheveux décolorés, réduire les pointes fourchues et renforcer leur résistance. Utiliser comme traitement revitalisant intense après le blondissement pour des cheveux plus forts et plus doux.

Pour des cheveux 97% plus hydratés et avec -63% de pointes fourchues*.

#YouDareWeCare

*Test instrumental après l''application du Masque Cicaextreme',46000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/70.png?v=1770204310',10,1,'8480733331631','46540782960815','https://beautymarket.ma/products/kerastase-blond-absolu-masque-cicaextreme-200ml-masque-reparateur-intense-cheveux-blonds',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/70.png?v=1770204310","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474636948529-200ml-masque-alt6.jpg?v=1771248941","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/B08SQLXKQG.PT07.jpg?v=1771248941","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474636692231-250ml-bain-ultra-alt5_c09c0cc3-2ffe-43da-a197-f48c0c6787de.jpg?v=1771253209","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474636948529-200ml-masque-alt2.jpg?v=1771248941"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Genesis Homme Bain de Force Quotidien 250ml – Shampooing Fortifiant Homme','Kérastase','Cheveux','Shampoing purifiant et fortifiant pour cheveux affaiblis ayant tendance à tomber.

Le Bain de Force Quotidien Genesis Homme de Kérastase est un shampoing purifiant et fortifiant, pour cheveux affaiblis ayant tendance à tomber. Sa triple action cuir chevelu, cheveux et barbe permet un nettoyage en douceur et en profondeur par l''élimination des excès de sébum et des impuretés. L''action du Bain de Force Quotidien provient de trois ingrédients principaux : la racine de gingembre, la Créatine et le menthol. Reconnue comme un stimulant favorisant la microcirculation des nutriments, la racine de gingembre a des effets protecteurs face aux agressions extérieures. La Créatine est un complexe d''acides aminés permettant la reconstruction et le renforcement de la structure du cheveu en boostant sa résistance. La présence de menthol apporte une sensation de fraîcheur. Dès la première application du Bain de Force Quotidien de Kérastase, votre cuir chevelu est nettoyé en douceur.

Vos cheveux sont instantanément plus forts, résistants et nourris.

94% des utilisateurs se disent satisfaits du Bain de Force Quotidien Genesis Homme de Kérastase(1)

Pour une routine complète, utilisez le Spray de Force Épaississant, ainsi que le Sérum Anti-Chute Fortifiant Genesis Homme de Kérastase.

(1)Test consommateur, réalisé auprès de 59 hommes',25500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/73.png?v=1770206365',10,1,'8480780976303','46540851839151','https://beautymarket.ma/products/kerastase-blond-absolu-cicaplasme-150ml-soin-thermo-protecteur-reparateur-cheveux-blonds',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/73.png?v=1770206365","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt01.jpg?v=1771536559","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt02.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt03.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt04.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt05.jpg?v=1771536558","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt06.jpg?v=1771536559","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt08.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt09.jpg?v=1771542475"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Genesis Homme Bain de Masse Épaississant 250ml – Shampooing Épaississant Homme','Kérastase','Cheveux','Shampoing booster d''épaisseur destiné aux cheveux affaiblis ayant tendance à s’affiner.

Le Bain de Masse Épaisissant est un shampoing volumateur issu de la gamme Genesis Homme de Kérastase. Destiné aux cheveux affaiblis ayant tendance à s''affiner, ce shampoing épaissit et texturise la fibre capillaire, apportant une sensation de volume. Sa triple action cuir chevelu, cheveux et barbe permet un nettoyage en douceur et en profondeur par l''élimination des excès de sébum et des impuretés. Idéal pour les cheveux fins, ce bain de Masse Épaississant est enrichi en deux ingrédients principaux : la racine de gingembre et la Créatine. Reconnue comme un stimulant favorisant la microcirculation des nutriments, la racine de gingembre a des effets protecteurs face aux agressions extérieures. La Créatine est un complexe d''acides aminés permettant la reconstruction et le renforcement de la structure du cheveu en boostant sa résistance. Dès la première application du Bain de Masse Épaisissant, votre cuir chevelu, vos cheveux et votre barbe sont nettoyés et hydratés en douceur. Le shampoing redonne corps et matière à la chevelure instantanément. Dès la première utilisation, le Bain de Masse Épaississant apporte plus de densité et jusqu''à +38%(1) de masse capillaire. Pour un résultat plus prononcé, avec +75%(2) de masse capillaire, complétez votre routine Genesis Homme avec la Cire d''Épaisseur Texturisante et le Sérum Anti-Chute Fortifiant.

(1)Test instrumental, après une application du Bain de Masse Épaississant',25500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/74.png?v=1770207530',10,1,'8480786677935','46540861407407','https://beautymarket.ma/products/kerastase-genesis-homme-bain-de-masse-epaississant-250ml-shampooing-epaississant-homme',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/74.png?v=1770207530","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077518.pt01.jpg?v=1771540237","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_22_GENESISHOMME_PDP_BAINDEMASSE2_2000x3000_03474637077518.jpg?v=1771540237","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt04.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt03.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt02.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt08.jpg?v=1771542475"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Genesis Homme Cire d’Épaisseur Texturisante 75ml – Cire Coiffante Épaississante','Kérastase','Cheveux','DESCRIPTION

Cire coiffante pour cheveux affaiblis ayant tendance à s''affiner.

La Cire d''Épaisseur Texturisante Genesis Homme de Kérastase est une cire coiffante pour cheveux affaiblis qui ont tendance à s''affiner. Idéale pour les cheveux fins, ses 3 lipides nutritifs permettent de prendre soin en profondeur de la fibre capillaire.
La Cire est enrichie en deux ingrédients principaux : la racine de gingembre et la Créatine. Reconnue comme un stimulant favorisant la microcirculation des nutriments, la racine de gingembre a des effets protecteurs face aux agressions extérieures.
La Créatine est un complexe d''acides aminés permettant la reconstruction et le renforcement de la structure du cheveu en boostant sa résistance. La cire épaissit les cheveux instantanément et fournit un effet texturisant aux cheveux pour faciliter le coiffage. Les cheveux sont 5 fois plus volumineux et les fibres sont 70%(1) plus épaisses.
Pour une routine complète et en fonction des besoins de vos cheveux, utilisez le Bain de Force Quotidien ou le Bain de Masse Épaississant, ainsi que le Sérum Anti-Chute Fortifiant de Genesis Homme.

(1)Test instrumental, après une application de la Cire d''Épaisseur + Bain de Masse Épaississant.',35500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/75_d5c18542-8a4e-4af5-8f1b-0f9e8ccbe817.png?v=1771541049',10,1,'8480793821359','46540872188079','https://beautymarket.ma/products/kerastase-genesis-homme-cire-d-epaisseur-texturisante-75ml-cire-coiffante-epaississante',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/75_d5c18542-8a4e-4af5-8f1b-0f9e8ccbe817.png?v=1771541049","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077594.pt01.jpg?v=1771541049","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_22_GENESISHOMME_CIRED_EPAISSEURTEXTURISANTE_03474637077594_TEXTURE2.jpg?v=1771541049","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_22_GENESISHOMME_CIREDEPAISSEURTEXTURISANTE_03474637077594_PRODUCTSINHAND.jpg?v=1771541049","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt04.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt02.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt03.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt08.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt09.jpg?v=1771542475"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Genesis Homme Sérum Anti-Chute Fortifiant 90ml – Soin Cuir Chevelu Homme','Kérastase','Cheveux','Kérastase Genesis Homme Sérum Anti-Chute Fortifiant 90ml – Soin Cuir Chevelu Homme

 Sérum Anti-Chute Fortifiant pour cheveux affaiblis ayant tendance à tomber

Sérum quotidien Anti-Chute Fortifiant pour les cheveux affaiblis, ayant tendance à tomber.

- Ralentit la chute de cheveux
- Aide les cheveux à s’ancrer plus solidement dans le cuir chevelu
- Apaise le cuir chevelu et limite les démangeaisons et inconforts.

Le Sérum Anti-Chute Fortifiant Genesis Homme ralentit la chute des cheveux dès 6 semaines*. Il s''applique quotidiennement le matin ou le soir. La chute de cheveux liée à la casse est réduite de 45%**.

Le Sérum renforce le cheveu à la racine. Il lutte contre la chute des cheveux et constitue un soin d’entretien quotidien qui fortifie la fibre capillaire en profondeur.',41500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/76.png?v=1770209611',10,1,'8480795164847','46540873531567','https://beautymarket.ma/products/kerastase-genesis-homme-serum-anti-chute-fortifiant-90ml-soin-cuir-chevelu-homme',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/76.png?v=1770209611","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/KER_22_GENESISHOMME_PDP_SERUM2_2000x3000_03474637077495.jpg?v=1770657383","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077495.pt01.jpg?v=1771542444","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt04.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt08.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt03.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt02.jpg?v=1771542475","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3474637077525.pt09.jpg?v=1771542475"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
