INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('dodot Couches Sensitive T2  4-8kg 58 Units','Dodot','Bébé & Maman','Couches Dodot Sensitive, 4-8 kg, Taille 2, paquet de 58.

