INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MAYBELLINE SUPERSTAY MATTE INK CHARMER N°510','Maybelline','Maquillage','MAYBELLINE SUPERSTAY MATTE INK CHARMER N°510

