INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MAYBELLINE FIT ME FOND DE TEINT LIQUIDE MATTE + PORELESS 30ML 105 NATURAL IVORY','Maybelline','Maquillage','Fond de teint Fit Me® Matte + Poreless. Ce fond de teint léger matifie et affine le grain de peau pour un fini naturel.

Bénéfices

