INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURASEPT BIOSMALTO BROSSE A DENTS JUNIOR 7-12 ANS','Curasept','Hygiène','Curasept Biosmalto Junior est une brosse à dents créée spécifiquement pour les jeunes de 7 à 14 ans. Elle aide à prévenir les caries en éliminant efficacement la plaque dentaire grâce aux poils fins et souples qui n''abîment pas la surface des dents de lait ou permanentes. La coloration de la les poils aident à doser la bonne quantité de dentifrice.',4200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-biosmalto-brosse-a-dents-junior-7-12-ans-brosses-a-dents-adultes.jpg?v=1770906887',10,1,'8484341121199','46559864357039','https://beautymarket.ma/products/curasept-biosmalto-brosse-a-dents-junior-7-12-ans',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-biosmalto-brosse-a-dents-junior-7-12-ans-brosses-a-dents-adultes.jpg?v=1770906887"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VITIS JUNIOR BROSSE A DENTS 6ANS+','Vitis','Hygiène','Cette brosse à dents conçue pour les enfants possède une petite tête et un coude court pour atteindre facilement toutes les parties de la bouche. Sa tête de brosse monotouffe spéciale élimine sans effort la plaque bactérienne la plus résistante.
Les soies de la brosse sont fabriquées en Tynex et pourvues d’un bout spécial qui élimine efficacement la plaque bactérienne (biofilm oral) sans endommager l’émail des dents ou la gencive.
Le manche ergonomique de la Brosse À Dents Vitis Junior, équipé de rainures antidérapantes, convient parfaitement aux mains des enfants de cet âge.
La Brosse À Dents Vitis Junior est livrée avec capuchon de protection en plastique, qui préserve les soies et garantit une hygiène optimale, en plus de permettre aux soies de sécher rapidement.',3800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vitis-junior-spazzolino-gel-15-ml.jpg?v=1770907001',10,1,'8484341350575','46559865307311','https://beautymarket.ma/products/vitis-junior-brosse-a-dents-6ans',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vitis-junior-spazzolino-gel-15-ml.jpg?v=1770907001"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NUXE HAIR PRODIGIEUX COFFRET LE RITUEL D''EXCEPTION CAPILLAIRE','Nuxe','Cheveux','Découvrez le rituel d''exception Hair Prodigieux® contenu dans un sac moumoute ultra-tendance pour vous accompagner tout l''hiver. Une routine de 3 soins au parfum iconique de l''Huile Prodigieuse®, pour des cheveux soyeux et éclatants de brillance.

Ce coffret soin cheveux contient:
-Hair Prodigieux® Le Shampoing Brillance Miroir 200ml
-Hair Prodigieux® Le Démêlant Brillance Miroir 200ml
-Hair Prodigieux® Le Masque Capillaire Réparation Intense 200ml

Soins formulés et fabriqués en France
Coffret 100% carton, 0% plastique et fabriqué en France.
Dimensions du sac : 25x9x20cm

Shampooing Brillance Miroir
Appliquez le shampooing Hair Prodigieux® sur vos cheveux mouillés, massez le cuir chevelu puis rincez.
Rincer en cas de contact avec les yeux.

Démêlant Brillance Miroir
Appliquez le démêlant Hair Prodigieux® sur vos cheveux humides et essorés en insistant sur les longueurs et les pointes. Laissez poser 1 minute puis rincez.
Rincer en cas de contact avec les yeux.

Masque Capillaire Réparation Intense
Appliquez sur les longueurs et pointes essorées, laissez poser 3 minutes, rincez.
Rincez en cas de contact avec les yeux.',70900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/coffret-noel-le-rituel-dexception-capillaire-9956936.webp?v=1770908438',10,1,'8484344103087','46559878054063','https://beautymarket.ma/products/nuxe-hair-prodigieux-coffret-le-rituel-dexception-capillaire',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/coffret-noel-le-rituel-dexception-capillaire-9956936.webp?v=1770908438"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDIN FOTOPROTECTOR FUSION WATER MAGIC REPAIR SPF50 50ML = 2 FUSION WATER MAGIC GLOW 10ML OFFERTS','Isdin','Solaires','ISDIN | FOTO ULTRA ISDIN® AGE REPAIR FUSION FLUID SPF50+ 50 ML
Foto Ultra ISDIN® Age Repair Fusion Fluid SPF50+ est un écran solaire conçu pour prévenir et freiner le photovieillissement.

