INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVUELE SHOWER GEL FRESHNESS BOOST, 400 ml','Revuele','Corps','Le Revuele Shower Gel Freshness Boost est un régal rafraîchissant pour votre expérience de douche quotidienne. Cette délicieuse formule combine des ingrédients soigneusement sélectionnés pour nettoyer et rajeunir votre peau, afin que vous puissiez profiter d''un moment de bien-être rafraîchissant au quotidien !

