INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVUELE Foam Soft Cleansing with chamomile extract, 150 ml','Revuele','Visage','Ce nettoyant visage doux nettoie en profondeur et élimine efficacement le maquillage et les impuretés. Grâce à ses ingrédients actifs, la mousse apaise, nourrit et rafraîchit la peau. L''extrait de camomille hydrate, nourrit et adoucit la peau. La mousse contient des ingrédients nettoyants doux qui hydratent et maintiennent l''équilibre hydrolipidique de la peau, améliorent son élasticité et lui procurent une sensation de confort et de fraîcheur.

