INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVUELE NO PROBLEM ANTI-PIMPLE PURIFYING LOTION SALICYLIC ACID, 200 ml','Revuele','Visage','REVUELE NO PROBLEM Lotion purifiante anti-boutons à l''acide salicylique. Ce produit exfolie et purifie en douceur votre visage des cellules mortes qui obstruent les pores et favorisent l''apparition de boutons et de points noirs. Il réduit la brillance et aide à prévenir les futures éruptions cutanées, pour une peau fraîche et saine. Conçu pour les peaux grasses et à tendance acnéique, il convient à un usage quotidien.

