INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE SUCETTE +6 MOIS DUO EXTRA FINE BLEU F3','Dodie','Autres soins','Les Sucettes Anatomiques Extra Modèle F3 de la marque pour bébés DODIE sont adaptées aux besoins des bébés âgés de 6 mois et plus.

Les sucettes sont extrêmement fines et souples avec une forme anatomique afin de réduire le risque de déformation du palais et de la mâchoire.

Au quotidien, elles apaisent bébé au moment de la succion sans pour autant gêner le bon développement de la bouche.

Ce qu’on aime avec ses sucettes c’est qu’elles possèdent un bouclier aéré afin de laisser la peau respirer librement.

Ainsi, pas d’irritations ou de démangeaisons autour de la bouche.

On aime les petits motifs colorés de ce modèle F3.

Les sucettes sont fabriquées en France, sans BPA ni BPS.',14200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-extra-sucettes-f3-2.webp?v=1771418655',10,1,'8486620790959','46572418695343','https://beautymarket.ma/products/dodie-sucette-6-mois-duo-extra-fine-bleu-f3',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-extra-sucettes-f3-2.webp?v=1771418655"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
