INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE SUCETTE A71 +18M DUO GIRLY / ANIMAUX RIGOLOS FILLE','Dodie','Bébé & Maman','DODIE SUC A71 +18M DUO GIRLY / ANIMAUX RIGOLOS FILLE Cette sucette anatomique convient aux bébés de plus de 6 mois.

