INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Kérastase Symbiose Fondant Apaisant Essentiel 200ML','Kérastase','Autres soins','Le Fondant Apaisant Essentiel de la gamme Symbiose de Kérastase est un soin démêlant apaisant destiné aux cuirs chevelus sensibles et à tendance pelliculaire.

