INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Beter Peigne Démêlant Ocean-12090 — Pink','Beter','Autres soins','Un peigne en plastique recyclé des océans

