INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURAPROX CPS 405 Perio Start 5 brossettes+manche 409/470','Curaprox','Hygiène','Offrez à votre hygiène bucco-dentaire un niveau de précision professionnel avec CURAPROX PERIO START 405, le kit idéal pour nettoyer efficacement les espaces interdentaires les plus larges, tout en respectant pleinement la sensibilité de vos gencives.',9300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3514bcad1acdf4533c6a44c0ae8cd60a.jpg?v=1772109640',10,1,'8490860675247','46593611628719','https://beautymarket.ma/products/curaprox-cps-405-perio-start-5-brossettes-manche-409-470',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3514bcad1acdf4533c6a44c0ae8cd60a.jpg?v=1772109640"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURAPROX CPS 011 Prime Start 5x + UHS409/451Manches, vert clair','Curaprox','Hygiène','Le Pack CPS 11 Prime Start Vert de Curaprox contient 5 brossettes interdentaires et 2 manches (1 manche UHS 409 et 1 manche UHS 470). Les brossettes interdentaires aident à éliminer toute la plaque dentaire et les résidus alimentaires susceptibles de sensibiliser vos dents et votre gencive. Elles nettoient les espaces étroits entre les dents afin de mieux prévenir les inflammations ou encore la mauvaise haleine.

Très fines, les brossettes interdentaires sont composées avec du fil métallique de qualité chirurgicale et des filaments très minces avec un effet parapluie pour un nettoyage optimal. Le système à encliquetage est très pratique, rapide et facile à utiliser. Les brossettes CPS 11 de Curaprox remplissent les espaces interdentaires sans provoquer de douleur, de gêne ou de saignement supplémentaire de la gencive. Un seul mouvement suffit afin d’avoir des espaces interdentaires propres.

Les brossettes interdentaires Curaprox conviennent aux adultes. Une seule utilisation, au moment du brossage des dents le matin par exemple, suffit pour avoir des dents propres et une haleine fraîche.

Le diamètre d''insertion est de 1.1mm et le diamètre d''efficacité est de 5.0mm.',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/6_603ef851-c594-4c53-9660-2414a2784c3f.png?v=1772110136',10,1,'8490861887663','46593615069359','https://beautymarket.ma/products/curaprox-cps-011-prime-start-5x-uhs409-451manches-vert-clair',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/6_603ef851-c594-4c53-9660-2414a2784c3f.png?v=1772110136"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
