INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMOZ GEL LAVANT SURGRAS PEAUX NORMALES A SECHES 400 ML','Dermoz','Visage','DERMOZ gel lavant surgras nettoie visage et peaux normales, sensibles, sèches à très sèches, respecte le film hydrolipidique et améliore le confort cutané. La peau est ainsi parfaitement nettoyée et reste hydratée. Adultes et enfants. Visage et corps.

Sa formule, enrichie d’un agent surgraissant, nourrit la peau en douceur apporte tous les plaisirs de nettoyage à l’eau sans ses effets desséchants. Sans savon, et formulé à pH physiologique, il préserve l’équilibre naturel cutané. Sa texture crème nacrée ne pique pas les yeux.',15900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7_3b24cdb7-63eb-40f3-8f75-285a1547f65e.png?v=1772206676',10,1,'8491461247151','46596244635823','https://beautymarket.ma/products/dermoz-gel-lavant-surgras-peaux-normales-a-seches-400-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7_3b24cdb7-63eb-40f3-8f75-285a1547f65e.png?v=1772206676"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
