INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NUXE Super Sérum [10] Concentré Anti-Age Universel 50ml - Toutes Peaux','Nuxe','Visage','Nuxe Super Serum [10] 50 ml est un sérum à l''acide hyaluronique, concentré anti-âge universel, qui agit sur la correction des rides, la fermeté, les taches.

Ce sérum à l''acide hyaluronique naturel est infusé de milliers de micro-billes d''huiles végétales fractionnées. Il stimule les mécanismes de jeunesse de la peau pour une extraordinaire efficacité anti-âge.
Dès les premières gouttes, la peau est lissée, repulpée, lumineuse. En quelques semaines, les rides et ridules sont estompées, la peau est progressivement plus lisse et plus ferme, les taches sont corrigées et le teint plus uniforme.
Une efficacité anti-âge et un plaisir ultime grâce à sa texture fraîche et soyeuse aux subtiles notes végétales, qui fond divinement sur la peau.

95% du total des ingrédients sont d''origine naturelle.

Vegan.',90200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/be1c242dd77224c480b69acab6f4cc12.jpg?v=1772535215',10,1,'8492607602863','46604940935343','https://beautymarket.ma/products/nuxe-super-serum-10-concentre-anti-age-universel-50ml-toutes-peaux',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/be1c242dd77224c480b69acab6f4cc12.jpg?v=1772535215","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nuxe-super-serum-p80233-g-2.jpg?v=1772535286"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
