INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BETER Hairstyle COFFEE O''CLOCK SERVIETTE TURBAN DE CHEVEUX 22286','Beter','Cheveux','Ce turban est fabriqué en microfibre extra-douce, il permet un séchage plus rapide des cheveux en éliminant l''excès d''humidité.

