INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR Sebiaclear Gel Active 40 ml = Gel Moussant 55ML Offert','SVR','Visage','Sebiaclear Active Gel est un produit dermatologique riche en principes actifs.
Sa formule puissante est conçue pour produire des résultats visibles en seulement sept jours.
