INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ABSOLUTE NEW YORK MULTIFACED COLORSTICK  STRAWBERRY COBBLER 04','Absolute New York','Maquillage','Complétez votre look avec les Multifaced Color Sticks d’Absolute New York, des sticks ultra polyvalents, parfaits pour une utilisation quotidienne.

Conçus pour être appliqués sur l’ensemble du visage, ces sticks multifonctions apportent dimension, ombres et couleur pour un rendu harmonieux, structuré et naturellement sophistiqué.

Appliquez, estompez, superposez sur les yeux, les joues et les lèvres pour un look monochrome facile et rapide à réaliser.

Comment ça fonctionne :

Le Multifaced Color Stick peut être utilisé sur les yeux, le visage et les lèvres.

À vous de jouer en mixant, associant et superposant les teintes pour créer un look sur mesure, avec une formule sans transfert pour une tenue longue durée.

✔ Résiste à la décoloration

✔ Résiste à l’eau

✔ Sans transfert

✔ Facile à estomper

✔ Léger sur la peau

✔ Modulable à souhait',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ABSOLUTENEWYORKMULTIFACEDCOLORSTICKSTRAWBERRYCOBBLER.webp?v=1773153034',10,1,'8539470889135','46668473663663','https://beautymarket.ma/products/absolute-new-york-multifaced-colorstick-strawberry-cobbler',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ABSOLUTENEWYORKMULTIFACEDCOLORSTICKSTRAWBERRYCOBBLER.webp?v=1773153034"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
