INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ABSOLUTE NEW YORK MAXI PLUMP LIP LINER WALNUT','Absolute New York','Maquillage','Maximisez l’effet lèvres pulpeuses avec le Maxi Plump Lip Liner, un crayon à lèvres waterproof qui offre un effet rafraîchissant et repulpant tout en définissant les lèvres. La teinte transparente sert à la fois de base (primer) et de liner, tandis que les autres teintes sont disponibles en cinq nuances — nude, marron, rose et rouge — parfaites pour accompagner n’importe quel produit pour les lèvres.

Associez‑le à notre Maxi Filler Lip Gloss pour doubler l’effet repulpant du crayon à lèvres !

Idéal pour les débutants, il permet une application facile et précise au‑dessus des lèvres sans bavure ni transfert.',7500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/888432020205.webp?v=1773152851',10,1,'8539471052975','46668473827503','https://beautymarket.ma/products/absolute-new-york-maxi-plump-lip-liner-walnut',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/888432020205.webp?v=1773152851"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
