INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ABSOLUTE NEW YORK VELVET FOCUS POWDER FOUNDATION-FAIR LIGHT NEUTRAL','Absolute New York','Maquillage','Cette poudre compacte légère et respirante est conçue pour estomper les imperfections, unifier le teint et contrôler la brillance, ce qui la rend parfaite pour tous les types de peau. Elle offre une couvrance modulable de moyenne à totale et un fini impeccable et radieux qui dure jusqu’à 12 heures.

Que vous cherchiez un fond de teint à porter au quotidien ou un produit longue tenue pour les retouches, cette poudre hautement pigmentée et facile à appliquer donne à votre peau un effet soft‑focus naturel, idéal pour une peau nue ou en superposition avec d’autres produits de maquillage.

Parfaite pour un look naturel ou modulable pour une couvrance complète.

Disponible en 5 magnifiques teintes.',11305,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/888432014105.webp?v=1773152062',10,1,'8539471249583','46668474810543','https://beautymarket.ma/products/absolute-new-york-velvet-focus-powder-foundation-fair-light-neutral',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/888432014105.webp?v=1773152062"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
