INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vhealth Vitaboost Hydration Multivitamines & Électrolytes Goût Fruit Rouge-10 Comprimés','Vhealth','Bien-être','VHealth Vitaboost Hydratation+ – Goût Fruit Rouge | Énergie & Vitalité Instantanées

