INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Erayba Always beautiful hair Spray 2 Phases Repair 200 ml – Réparateur & Protecteur Anti-UV','Erayba','Cheveux','Le ABH Repair 2-Phase Conditioner 200ml est un soin sans rinçage innovant conçu pour offrir une réparation instantanée et une protection durable à vos cheveux. Avec sa formule biphasée avancée, ce conditionneur pénètre rapidement pour revitaliser les cheveux abîmés, leur redonner douceur et les protéger des agressions extérieures.

