INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RELOVE LIPLINER GLAM','Revolution','Autres soins','Glam-Up ! … Le dernier né d''une famille sympa et incroyablement de chez Makeup Revolution abordable nous propose une gamme étonnante avec une texture et une pigmentation exceptionnelle.

