INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RELOVE POWER BROW PENCIL BROWN','Revolution','Autres soins','Créez des sourcils naturels et précis avec le crayon à sourcils Relove Power Brow Pencil. Ce crayon double embout est doté d''une large mine biseautée pour dessiner des traits semblables à ceux des poils et d''un goupillon pour dégrader la matière et brosser vos sourcils dans le sens et la forme que vous désirez.

