INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RELOVE SUPER HIGHLIGHT BLUSHED','Revolution','Maquillage','Brillez de mille feux avec les highlighters Relove Super Highlight. Disponible en 8 teintes éblouissantes qui conviennent à toutes les carnations. Ces highlighters abordables et pigmentés offrent un fini surprenant en un seul coup de pinceau.

Conseils d''utilisation : À l''aide d''un pinceau à highlighter, appliquez la matière sur l''arête du nez, l''arc de cupidon, l''arcade sourcilière, les pommettes, le coin interne des yeux et même les clavicules pour un éclat naturel ou glamour. Si vous recherchez un glow encore plus percutant, humidifiez au préalable votre pinceau à l''aide d''un spray fixateur.',4500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1511216-Revlove-SuperHighlight-Blushed-2-3369x3369-266f3afd-6087-4a3d-a63f-6054b23b5a70.jpg?v=1774899878',10,1,'8547977167023','46719290310831','https://beautymarket.ma/products/relove-super-highlight-blushed',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1511216-Revlove-SuperHighlight-Blushed-2-3369x3369-266f3afd-6087-4a3d-a63f-6054b23b5a70.jpg?v=1774899878","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1511216-Revlove-SuperHighlight-Blushed-1-720x720-ecd40322-7d68-4884-ae0d-94612219153c.webp?v=1774901984","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1511216-Revlove-SuperHighlight-Blushed-3-720x720-2a7ec399-062b-4165-b8c9-6e738ec9e28f.webp?v=1774901984","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RELOVESuperHighlightswatch_c07eccb8-3ff4-43b4-8463-6f8a4ec11543_1.jpg?v=1774902204"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RELOVE SUPER MATTE PRESSED POWDER TRANSLUCENT','Revolution','Maquillage','Fan de mat ? La poudre de finition Revolution Super Matte Pressed Powder est pour vous ! Mat, mat, mat ! C''est avec ce mantra en tête que nous avons développé cette poudre. Le look dewy n''est pas pour tout le monde après tout !

Votre alliée pour créer une base mate. Au lancement, cette poudre développée pour vous aider à obtenir un fini mat impeccable sera disponible en 12 teintes. Disponible dans plusieurs sous-tons, cette poudre légère et douce se fond sans effort dans la peau pour un fini naturel. Dites adieu à la brillance !

Très pigmentée, cette poudre légère est LA solution pour les peaux grasses, ou pour les personnes qui aiment tout simplement le mat.

Conseils d''utilisation :

Après avoir mis votre base, appliquez le produit à l''aide d''un pinceau à poudre pour obtenir une couvrance moyenne et un fini flouté. Pour une couvrance plus élevée, appliquez par-dessus votre fond de teint mat préféré pour obtenir un fini parfaitement mat et lisse. Réappliquez dans la journée où que vous soyez si la brillance repointe le bout de son nez !

Dans la même collection, utilisez aussi : Le fond de teint Revolution Conceal & Define Foundation, disponible en plusieurs teintes. Vegan. Cruelty-free.

Disponible en 3 références:

Translucide
Vanilla - Pour les peaux claires avec un sous-ton neutre – F2
Beige - Pour les peaux claires/medium avec un sous-ton neutre – F5',4500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1870078-Relove-Super-Matte-Pressed-Powder-Translucent-1_None-2000x2000-d6224b86-f642-4d70-958b-098e33fb1da2.webp?v=1786792892',10,1,'8547977265327','46719290409135','https://beautymarket.ma/products/relove-super-matte-pressed-powder-translucent',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1870078-Relove-Super-Matte-Pressed-Powder-Translucent-1_None-2000x2000-d6224b86-f642-4d70-958b-098e33fb1da2.webp?v=1786792892","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1870078-Relove-Super-Matte-Pressed-Powder-Translucent-3_None-2000x2000-874f16a8-41a7-44a2-8977-a08d199af6b7.webp?v=1786792926","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1870078-Relove-Super-Matte-Pressed-Powder-Translucent--2000x2000-18130d29-1911-4c31-b6d7-2ae8d0672a66.webp?v=1786792926","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RELOVESuperMattePressedPowderBeige4_d9edb17b-d3b0-47e1-9cdd-5425a4d20a20.webp?v=1786792925"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
