INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Periokin Bain de Bouche 250ml','Kin','Hygiène','Periokin Bain de Bouche 250ml

Bain de bouche antiseptique – Hygiène bucco-dentaire et protection des gencives

