INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Technic Summer Triple Wave Serum Foundation - Fair','Technic','Cheveux','Obtenez une peau éclatante et hydratée avec ce fond de teint sérum non gras et léger.

Triple Wave est un fond de teint à la fois soin et maquillage conçu pour se fondre parfaitement dans la peau et aider à couvrir le teint irrégulier et les imperfections.

La formule hydratante est enrichie d’ingrédients doux pour la peau tels que l’acide hyaluronique, la glycérine et la vitamine E. Cette formule aide à donner une hydratation durable pour une base d’apparence impeccable tout au long de la journée. Le fond de teint offre un fini demi-mat avec une couvrance moyenne, parfait pour un look naturel mais soigné.

💧 Convient aux végétaliens

💧 Fond de teint sérum triplement infusé

💧 Texture légère et soyeuse

💧 Formule hydratante à la fois soin et maquillage

💧 Contient de l’acide hyaluronique, de la vitamine E et de la glycérine

💧 Fini demi-mat avec une couvrance légère et moyenne',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/24719TripleWave-fair-wc-sq_1296x_c83626b4-09d6-4e94-b7e5-a16902e21745.webp?v=1775498450',10,1,'8551255998639','46744166301871','https://beautymarket.ma/products/technic-summer-triple-wave-serum-foundation-fair',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/24719TripleWave-fair-wc-sq_1296x_c83626b4-09d6-4e94-b7e5-a16902e21745.webp?v=1775498450"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
