INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dermoz Gel Silicon Cicatrisant 40ml','Dermoz','Autres soins','Dermoz Gel Silicon Cicatrisant 40ml

