INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SEVEN KIDS LAIT CORPOREL 400ML','seven kids','Bébé & Maman','Le lait corporel SEVEN KIDS est un produit de haute qualité conçu pour soigner et protéger la peau des plus petits de la maison. Avec une formule douce et délicate, ce lait corporel est parfait pour hydrater et nourrir la peau des enfants, la gardant douce et saine.

