INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Forte Pharma Xtra Slim Chrono Minceur et perte de poids 450ml','Forte Pharma','Bien-être','Le département Recherche & Développement des Laboratoires Forté Pharma a mis au point XtraSlim CHRONO DETOX MINCEUR, une formule spécialement conçue pour vous aider à optimiser votre programme minceur. Complète et innovante, elle est composée de 8 ingrédients sélectionnés avec soin :

