INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Pack 2 biberons Natural Start 340 ml','Tommee Tippee','Bébé & Maman','Notre biberon le plus proche du sein, jamais conçu. Il facilite la transition entre le sein et le biberon. Tétine souple en silicone, flexible et extensible comme le sein. Valve anti-coliques pour soulager les gaz de bébé. Auto-stérilisation rapide en seulement trois minutes au micro-ondes*. 100 % étanche avec le couvercle (même à l''envers). Sans BPA. *Basé sur une utilisation au micro-ondes entre 700 et 1000 W.',14100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/uz4b0vhyyrsjynyxsr4v_1_1a57e3f2-09bb-4439-b183-340a95bd4934.webp?v=1784040274',10,1,'8603593408687','47000706810031','https://beautymarket.ma/products/tommee-tippee-pack-2-biberons-natural-start-340-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/uz4b0vhyyrsjynyxsr4v_1_1a57e3f2-09bb-4439-b183-340a95bd4934.webp?v=1784040274","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/j718fis4z0ricrjmig3e_90f3c90b-82e3-45b1-81b2-ad1fa22344df.webp?v=1784040278","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/caxeegudac0szvqiwr3d_525f3ce7-a87b-4602-9715-f5b34c2f5aa8.webp?v=1784040280","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hmhbzgqufwyame6dw14f_df54c976-1ed5-4564-91b7-69891d69d9c7.webp?v=1784040281"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
