INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Pack 2 tétines débit lent','Tommee Tippee','Autres soins','Nos tétines Natural Start, imitant la sensation du sein, sont conçues pour réduire la confusion sein-tétine et faciliter la transition entre le sein et le biberon*. Le silicone souple et extensible offre un confort familier, tandis que la large zone de succion et les ondulations flexibles favorisent une prise en bouche naturelle. • 95 % des bébés acceptent le biberon Tommee Tippee* • Valve anti-coliques intégrée, prouvée pour réduire l''ingestion d''air* • Compatible avec tous les biberons Tommee Tippee Natural Start • Sans BPA • Un choix idéal de tétine (et de débit) pour chaque étape de l''allaitement, dès la naissance et au-delà. Extra Lent : Pour les premières tétées. Avec la plus petite ouverture pour un rythme doux, aidant bébé à s''habituer à la succion au biberon. Lent : Pour les nouveau-nés et les bébés de moins de 3 mois. Avec une petite ouverture pour des tétées plus lentes . Moyen : Pour les bébés de 3 mois et plus. Avec une ouverture moyenne pour des tétées à rythme moyen. Rapide : Pour les bébés de 6 mois et plus. Avec la plus grande ouverture pour des tétées plus rapides. Varié : À utiliser dès la naissance et au-delà. La découpe en forme de X permet à bébé de contrôler le débit. Nous recommandons de remplacer les tétines des biberons de votre bébé tous les 2 mois ou dès les premiers signes d''usure ou de faiblesse.',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42458401-TTNS2XSLOWFLOWTEATALAR05.07.23_1_1_1.jpg?v=1780508831',10,1,'8603593506991','47000706908335','https://beautymarket.ma/products/tommee-tippee-pack-2-tetines-debit-lent',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42458401-TTNS2XSLOWFLOWTEATALAR05.07.23_1_1_1.jpg?v=1780508831","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/CTNSlowFlowNipple_productonly_1.jpg?v=1780504672","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_NaturalStart_Teat_Carrousel_05ClaimDesign.jpg?v=1780504702","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_NaturalStart_Teat_Carrousel_Educational.jpg?v=1780504705","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_NaturalStart_Bottle260ml_Carrousel_03KeyFeatures_1.jpg?v=1780504711","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_NaturalStart_Teat_MediumFlow_Carrousel_02MAINUSP-2.jpg?v=1780504716"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
