INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Pack 2 tétines débit moyen anti-colique avancé','Tommee Tippee','Autres soins','Cette tétine spécialement conçue est compatible avec nos biberons anti-coliques avancés pour réduire les symptômes des coliques. Moins de gaz, moins de stress, plus de sommeil. Sa forme imite le sein pour une succion naturelle. Elle s''utilise avec notre tige ventilée brevetée pour réduire les gaz et l''inconfort. Le silicone souple est flexible et extensible comme un sein . Différents débits permettent à bébé de se nourrir à son rythme. Sans BPA.',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42112853-TT2XADVACMEDFLOWTEATAL_1.jpg?v=1780505664',10,1,'8603593703599','47000707104943','https://beautymarket.ma/products/tommee-tippee-pack-2-tetines-debit-moyen-anti-colique-avance',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42112853-TT2XADVACMEDFLOWTEATAL_1.jpg?v=1780505664","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/52290511AACMediumFlowNipples_1.png?v=1780505666","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_AU__AAC_Teat_Carrousel_03KeyFeatures_1.jpg?v=1780505690","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/US_NSTeats_Carrousel_Educational_1.jpg?v=1780505685"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Biberon anti-colique 260 ml débit lent','Tommee Tippee','Bébé & Maman','Scientifiquement prouvé pour soulager les gaz de bébé, avec une tétine ventilée pour un confort optimal pendant la tétée†. Moins de gaz, moins de stress, plus de sommeil. Tétine ventilée brevetée pour évacuer l''air du ventre de bébé. Tétine en silicone souple et extensible. Auto-stérilisation rapide en seulement trois minutes au micro-ondes. 100 % étanche avec le couvercle (même à l''envers). Sans BPA . †Comparativement à 10 biberons leaders du marché, la valve CAA nécessite moins de force pour être activée.',9000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42256987ALAR1X260MLAAC.jpg?v=1780505880',10,1,'8603593736367','47000707137711','https://beautymarket.ma/products/tommee-tippee-biberon-anti-colique-260-ml-debit-lent',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42256987ALAR1X260MLAAC.jpg?v=1780505880","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42274501AAC1X260MLBOTTLEUKLID1.jpg?v=1780505888","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BottlesrebrandAACaltimage5.jpg?v=1780505869","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BottlesrebrandAACaltimage4.jpg?v=1780505871","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/AACBottle260ml_BulletPoints_Carrousel_4_UK-AU.jpg?v=1780505874","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/AAC_Bottle260ml_Carrousel_2.jpg?v=1780505877"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Biberon Natural Start 260 ml','Tommee Tippee','Bébé & Maman','Notre biberon le plus proche du sein maternel, jamais conçu. Facilite la transition entre le sein et le biberon*. Tétine souple en silicone, flexible et extensible comme le sein. Valve anti-coliques pour soulager les gaz de bébé. Auto-stérilisation rapide en seulement trois minutes au micro-ondes. 100 % étanche avec le couvercle (même à l''envers). Sans BPA. *Basé sur une utilisation au micro-ondes entre 700 et 1000 W.',11300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/422871TTNS1X260MLBOTTLEALAR.jpg?v=1780505978',10,1,'8603593801903','47000707203247','https://beautymarket.ma/products/tommee-tippee-biberon-natural-start-260-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/422871TTNS1X260MLBOTTLEALAR.jpg?v=1780505978","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/422871SA1X340MLNSBOTTLE.jpg?v=1780505973","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK-AU-NaturalStart-DTC-Carousel-Claim-05_1.jpg?v=1780505966","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_AU__NaturalStart_Bottle260ml_Carrousel_03KeyFeatures_2.jpg?v=1780505968","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK-AU-NaturalStart-DTC-Carousel-MainUSP-02.jpg?v=1780505971"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Biberon verre Natural Start 250 ml','Tommee Tippee','Bébé & Maman','Les biberons en verre Tommee Tippee Natural Start sont résistants et sans danger pour les bébés. Conçus pour durer et garder leur aspect neuf plus longtemps, ces biberons en verre borosilicate sont résistants aux rayures et aux taches et n''absorbent ni les odeurs ni les saveurs du lait maternel ou infantile. Avec leur tétine imitant le sein, les biberons Natural Start sont idéaux pour passer facilement du sein au biberon et inversement*. Ils sont dotés d''un système d''auto-stérilisation intelligent et d''une valve anti-coliques intégrée à la tétine, dont l''efficacité pour réduire l''ingestion d''air est prouvée*. • Fabriqués en verre borosilicate sans danger pour les bébés • 95 % des bébés acceptent les biberons Tommee Tippee* • Auto-stérilisation en 3 étapes  : 1. Versez 50 ml d''eau (en suivant le repère pointillé) 2. Posez le couvercle, la bague et la tétine assemblés sur le dessus (sans les visser) 3. Passez au micro-ondes pendant 3 minutes • Étanches avec le couvercle (même à l''envers) • Sans BPA, BPS ni phtalates',19800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42243891TTNSGLASS1X250MLBTLALAR_1.jpg?v=1780506053',10,1,'8603593834671','47000707236015','https://beautymarket.ma/products/tommee-tippee-biberon-verre-natural-start-250-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42243891TTNSGLASS1X250MLBTLALAR_1.jpg?v=1780506053","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/42243891_TTNSGLASS1X250MLBTLALAR_1.jpg?v=1780506052","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_NaturalStart_Bottle260ml_Carrousel_05CLAIMDESIGN_DTC.jpg?v=1780506048","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_GlassBottle_Carrousel_09Educational_AMZ.jpg?v=1780506049","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_GlassBottle_Carrousel_03KeyFeatures.jpg?v=1780506050"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
