INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee - Gobelet enfant 12 mois 390 ml — Blue','Tommee Tippee','Autres soins','Qu’ils rampent, marchent ou courent, les tout-petits ont soif ! Notre gobelet anti-fuites à bec large est conçu pour faciliter leur transition vers le verre. Convient aux bébés de 12 mois et plus. • Le bec large imite la forme d’un verre, aidant ainsi les tout-petits à boire dans un verre ouvert et incurvé. • La valve intelligente en deux parties empêche les fuites (mais peut être retirée pour boire librement). • Le bec monobloc est doux pour les gencives qui font leurs dents (et reste résistant aux morsures). • Le couvercle amovible permet de garder le bec propre. • Compatible avec le stérilisateur et le lave-vaisselle, sans BPA.',12200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/448007_EMEA_1X_12M__TODDLER_SIPPER_BLUE.jpg?v=1784035159',10,1,'8603594457263','47173581832367','https://beautymarket.ma/products/tommee-tippee-gobelet-enfant-12-mois-390-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/448007_EMEA_1X_12M__TODDLER_SIPPER_BLUE.jpg?v=1784035159","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_Toddler_Sipper_Cup_Carrousel_7.jpg?v=1784035426","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_Toddler_Sipper_Cup_Carrousel_4.jpg?v=1784035435","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UK_Toddler_Sipper_Cup_Carrousel_6.jpg?v=1784035428","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/448007_Blue.jpg?v=1784035244","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/448007_Purple.jpg?v=1784035326","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/448007_Green.jpg?v=1784035323"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
