INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee  Bol bébé avec couvercle et cuillère','Tommee Tippee','Bébé & Maman','Bols pour bébé avec couvercles de rangement sécurisés et cuillère de diversification alimentaire facile à prendre en main. Conçus pour faciliter le service (et le dosage) des purées et des aliments solides. Poignée ergonomique pour garder les mains propres. Des repas sans dégâts, même en déplacement. • Couvercle anti-fuites maintenant la cuillère en place et évitant les débordements, pour un rangement facile et moins de dégâts • Bols empilables pour un gain de place • Convient aux bébés de 6 mois et plus • Sans BPA, BPS, PVC, phtalates ni nitrosamines • Compatibles lave-vaisselle, micro-ondes, stérilisateur et congélateur',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/5010415467188_2_34c42c2c07ffd777825ca3ed80cd08c8.jpg?v=1784029528',10,1,'8603594588335','47000708055215','https://beautymarket.ma/products/tommee-tippee-bol-bebe-avec-couvercle-et-cuillere',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/5010415467188_2_34c42c2c07ffd777825ca3ed80cd08c8.jpg?v=1784029528","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/5010415467188_8e285b93952b3fdd4b5bd0264f208a7e.jpg?v=1784029507"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
