INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GARNIER SUPER UV COOLING GEL 60ML','Garnier','Solaires','Découvrez notre premier écran solaire rafraîchissant, conçu pour offrir une sensation immédiate de -2°C et une fraîcheur qui dure jusqu''à 8 heures*. Sa formule gel SPF 50+/PA++++ offre une protection à 99% contre les dommages liés au soleil (taches, pigmentation et teint irrégulier).

Le petit plus ? Tandis que la Vitamine C, notre actif booster d''éclat, renforce l''efficacité de la protection solaire et corrige les taches, les actifs rafraîchissants protègent votre peau des signes de stress thermique (pores obstrués, sensibilité accrue et imperfections).

Ce gel solaire résiste à la transpiration, tandis que sa texture "water-gel" ultra-légère offre un fini invisible. Il pénètre rapidement et se glisse parfaitement sous le maquillage, sans effet de matière ni traces blanches. Affrontez les pics de chaleur comme un pro et profitez d''un soin tout-en-un (protection, fraîcheur, confort et éclat) avec le gel solaire Garnier.

Le saviez-vous ? Sa formule est testée dermatologiquement et non comédogène : elle convient parfaitement aux peaux normales, grasses, à tendance acnéique ou sensibles.

Comment l''utiliser: Appliquez uniformément sur le visage et le cou comme dernière étape de votre routine de soin matinale. Renouvelez l''application toutes les 2 à 3 heures pour une protection maximale.

Bénéfices Consommateur: SOLAIRE UV À LARGE SPECTRE SPF 50+ : Ce solaire à la texture gel offre une protection à large spectre contre les UVA/UVB, garantissant 99 % de protection contre les dommages cutanés liés au soleil.

8H DE FRAÎCHEUR & SENSATION COOLING INSTANTANÉE DE -2°C :* Boosté par des actifs rafraîchissants, le solaire Garnier Super UV Watergel procure une fraîcheur durable et une sensation de froid immédiate à l''application.

RÉSISTE À LA CHALEUR & À LA TRANSPIRATION : Sa formule gel protectrice préserve votre peau des effets de la chaleur (pores obstrués, sensibilité accrue, transpiration et imperfections).

ILLUMINE & CORRIGE LES TACHES SOLAIRES : Grâce à sa formule enrichie en Vitamine C, il aide à corriger les taches brunes dues au soleil et révèle l''éclat de votre teint.

NON COMÉDOGÈNE & IDÉAL SOUS LE MAQUILLAGE : Le gel Garnier Super UV est testé dermatologiquement, non comédogène et s''applique facilement sous le maquillage. Convient aux peaux normales, grasses, sensibles ou à tendance acnéique.',7900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/colling1.png?v=1768505514',10,1,'8607030018223','47016046035119','https://beautymarket.ma/products/garnier-super-uv-cooling-gel-60ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/colling1.png?v=1768505514","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cooling.png?v=1768505514","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_5.png?v=1778865074","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_2_9f95a57c-41dd-420e-a405-b8d3f7872cec.png?v=1778865068","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_3.png?v=1778864984","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_6.png?v=1778865075","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_3_e48c207d-de3e-4dec-beac-d990e47d0676.png?v=1778865070","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_4.png?v=1778865072","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_8.png?v=1778865079","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8901526680573_7_1.png?v=1779460301","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/08_CFI_VEGAN.jpg?v=1768563039"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
