INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La Roche-Posay Anthelios UVAIR Sérum Solaire SPF50+ Tous types de peaux 50ml','La Roche-Posay','Solaires','Nouveau Anthelios UVAIR Sérum Solaire SPF50+ de La Roche-Posay, conçu pour minimiser l’impact de la photopollution sur la peau, il offre 16 h d’action antioxydante et 24 h d’hydratation.
