INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Nuxe Sun Crème fondante SPF50 50ml = Lait fraîcheur après-soleil 50ml Offert','Nuxe','Solaires','Nuxe Sun Crème Fondante SPF50 50ml = Lait Fraîcheur Après-Soleil 50ml Offert

