INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ERIC FAVRE Pure White+ Maxi  Glutathion 1000 mg','Eric Favre','Cheveux','L’EXPERTISE AU SERVICE DE VOTRE ÉCLAT

