INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GILLETTE VENUS COMFORTGLIDE 4 PCS BREEZE 3 LAMES DE RASAGE COMFORT GLIDE BREEZE','Gillette Venus','Autres soins','Votre peau mérite un rasage de niveau supérieur. C''est pourquoi les recharges de Lames Gillette Venus ComfortGlide pour femme ont été conçues en tenant compte de votre peau unique. Transformez votre routine de rasage en une journée détente au spa.

