INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HARTMANN MOLICARE PREMIUM CHANGE ADULTE ELASTIC 7G TAILLE L NUIT 30U','Hartmann','Hygiène','MoliCare Premium Elastic HARTMANN est un change complet avec ailes élastiquées.
