INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HARTMANN MOLICARE PR BED MAT 7GT ALÈSES 60*90 30U','Hartmann','Hygiène','Draps de lit d’incontinence à usage unique – une protection sûre et hygiénique contre les fuites qui simplifie le quotidien des soignants. Testé dermatologiquement.

Draps de lit d’incontinence à usage unique pour des soins sûrs et hygiéniques

