INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Filorga DAILY REPAIR MINERAL UV 50-Fluide hydratant protecteur quotidien 50 ml','Filorga','Solaires','DAILY REPAIR MINERAL 50 UV est un écran solaire quotidien 100% minéral au fini invisible spécifiquement formulé pour renforcer la barrière cutanée, protéger la peau contre les rayons UV et apaiser les peaux sensibles tout en offrant une hydratation longue durée.

