INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ACM SÉBIONEX HYDRA CRÈME 40 ML = PAIN DERMATOLOGIQUE PURIFIANT 100 G OFFERT','ACM','Visage','Les traitements dermatologiques anti-acnéiques ou les agressions extérieures ont tendance à rendre la peau plus sèche ; ce soin restaure leur confort cutané.

