INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LCP REPULSIF MOUSTIQUES LOTION 8H 60 ML','LCP','Autres soins','Que vous soyez à la maison, en voyage, en vacances ou lors d''activités en plein air, cette lotion offre une protection durable adaptée aux zones où les moustiques sont particulièrement présents. Son format compact de 100 ml permet de l''emporter facilement dans un sac, une trousse de voyage ou une poche afin de rester protégé à tout moment.

