INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION AIR BLUR MATTE LIQUID LIPSTICK DREAMY','Revolution','Maquillage','Les rouges à lèvres mats sont de retour! La gamme Air Blur vous promet des lèvres audacieuses!

C''EST FLOU, C''EST FOU!

Nouveauté: Air Blur, des rouges à lèvres liquides mats et hydratants pour une bouche qui attirera tous les regards… Leurs promesses? Des teintes audacieuses, une formule nourrissante et protectrice, un complexe réconfortant de vitamine E, d''huile de graines de jojoba et d''huile de graines de limnanthe pour une moue gourmande et pulpeuse.

Les rouges à lèvres mats sont de retour! Portez-les à votre façon grâce à la gamme Air Blur à la formule douce et fouettée. Appliquez sur les lèvres directement au doigt pour un fini flouté soft-focus ou bien superposez les couches avec l''applicateur pratique pour une pigmentation plus audacieuse!

LES PROMESSES DES ROUGES À LÈVRES AIR BLUR
Une haute pigmentation et un fini flouté soft-focus
Une formule veloutée et onctueuse sans effet matière, ni assécher ni craqueler les lèvres
Enrichi en un complexe réconfortant d''ingrédients bons pour les lèvres, notamment de la vitamine&nbsp;E (pour des lèvres en pleine santé), de l''huile de graines de jojoba (pour les nourrir) et de l''huile de graines de limnanthe (pour les hydrater)
Longue tenue et très fin sur les lèvres
Un applicateur en forme de goutte pour une bouche onctueuse en un instant

Disponible en :

Chauffeur - Nude Foncé
Dreamy – un rouge froid
Sultry – un mauve foncé chaud
Peachy – un rose pâle aux sous-tons violets

CONSEILS D''UTILISATION:
Appliquez sur vos lèvres grâce à l''applicateur en forme de goutte. Commencez par l''arc de cupidon et le contour de vos lèvres, puis remplissez-les pour obtenir un fini mat et homogène. Tapotez délicatement du bout des doigts pour flouter les contours.

Astuce de pro: Superposez les couches pour une pigmentation plus intense.

Cruelty-free et vegan.',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1840682-Revolution-Air-Blur-Matte-Liquid-Lipstick-Dreamy-1.webp?v=1783010398',10,1,'8625374429359','47134157897903','https://beautymarket.ma/products/revolution-air-blur-matte-liquid-lipstick-dreamy',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1840682-Revolution-Air-Blur-Matte-Liquid-Lipstick-Dreamy-1.webp?v=1783010398","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1840682-Revolution-Air-Blur-Matte-Liquid-Lipstick-Dreamy-3.webp?v=1783010399","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Dreamy-Model-Swatch-1x1.webp?v=1783010398"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION AIR BLUR MATTE LIQUID LIPSTICK PEACHY','Revolution','Maquillage','Les rouges à lèvres mats sont de retour! La gamme Air Blur vous promet des lèvres audacieuses!

C''EST FLOU, C''EST FOU!

Nouveauté: Air Blur, des rouges à lèvres liquides mats et hydratants pour une bouche qui attirera tous les regards… Leurs promesses? Des teintes audacieuses, une formule nourrissante et protectrice, un complexe réconfortant de vitamine E, d''huile de graines de jojoba et d''huile de graines de limnanthe pour une moue gourmande et pulpeuse.

Les rouges à lèvres mats sont de retour! Portez-les à votre façon grâce à la gamme Air Blur à la formule douce et fouettée. Appliquez sur les lèvres directement au doigt pour un fini flouté soft-focus ou bien superposez les couches avec l''applicateur pratique pour une pigmentation plus audacieuse!

LES PROMESSES DES ROUGES À LÈVRES AIR BLUR
Une haute pigmentation et un fini flouté soft-focus
Une formule veloutée et onctueuse sans effet matière, ni assécher ni craqueler les lèvres
Enrichi en un complexe réconfortant d''ingrédients bons pour les lèvres, notamment de la vitamine&nbsp;E (pour des lèvres en pleine santé), de l''huile de graines de jojoba (pour les nourrir) et de l''huile de graines de limnanthe (pour les hydrater)
Longue tenue et très fin sur les lèvres
Un applicateur en forme de goutte pour une bouche onctueuse en un instant

Disponible en :

Chauffeur - Nude Foncé
Dreamy – un rouge froid
Sultry – un mauve foncé chaud
Peachy – un rose pâle aux sous-tons violets

CONSEILS D''UTILISATION:
Appliquez sur vos lèvres grâce à l''applicateur en forme de goutte. Commencez par l''arc de cupidon et le contour de vos lèvres, puis remplissez-les pour obtenir un fini mat et homogène. Tapotez délicatement du bout des doigts pour flouter les contours.

Astuce de pro: Superposez les couches pour une pigmentation plus intense.

Cruelty-free et vegan.',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1842396-Revolution-Air-Blur-Matte-Liquid-Lipstick-Peachy-1_1.webp?v=1783011102',10,1,'8625375117487','47134161698991','https://beautymarket.ma/products/revolution-air-blur-matte-liquid-lipstick-peachy',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1842396-Revolution-Air-Blur-Matte-Liquid-Lipstick-Peachy-1_1.webp?v=1783011102","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1842396-Revolution-Air-Blur-Matte-Liquid-Lipstick-Peachy-3.webp?v=1783011102","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/0000_ROBIN_PEACHY_TINT_WITH-PRODUCT0884_Green_1.webp?v=1783011102"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
