INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BABARIA CREME CORPORELLE APRES SOLEIL FRAICHE A L''ALOE VERA 400ml','BABARIA','Solaires','Découvrez la Crème Corporelle Après-Soleil Fraîche à l''Aloe Vera Babaria 400ml sur notre site e-commerce. Après une journée ensoleillée, votre peau mérite une hydratation et un soin apaisants. Cette crème corporelle après-soleil Babaria est spécialement conçue pour offrir un soulagement instantané et une réparation profonde à votre peau exposée au soleil.

