INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEEDLY Anti Trouble Pad 60 Pads','Needly','Visage','NEEDLY Anti Trouble Pad 60 Pads

