INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''ORÉAL PARIS MEN EXPERT GEL DOUCHE DERMA CONTROL 300ML','L''Oréal Paris','Visage','La Puissance de l''Acide Hyaluronique pour le Corps

